    #region Private Data
    // Qualified: in the merged single assembly the `Daqifi.Desktop.Logger` namespace
    // (upstream Loggers files) shadows NLog.Logger from any Daqifi.Desktop.* scope.
    private readonly NLog.Logger? _logger;
    private IDisposable? _sentryDisposable;
    private static readonly bool IsTestMode = IsRunningInTestEnvironment();
