    // @port: Daqifi.Desktop.Common.Loggers.AppLogger.Instance
    public static AppLogger Instance { get; } = new();

    /// <summary>
    /// Finds the Sentry DSN from the first source that has one.
    /// </summary>
    /// <remarks>
    /// Upstream reads only <c>ConfigurationManager.AppSettings</c>, which is an App.config
    /// mechanism. This repo has no App.config on any head, and Android cannot have one, so
    /// that lookup returned nothing everywhere and Sentry was silently inert on desktop as
    /// well as mobile — the package was referenced and the manifest carried its meta-data,
    /// but <c>SentrySdk.Init</c> was never reached.
    /// <para>
    /// Order is deliberate: an explicit App.config or environment value should win over the
    /// compiled-in default, so a developer or CI run can redirect events away from the
    /// production project without editing the build.
    /// </para>
    /// </remarks>
    private static string? ResolveSentryDsn()
    {
        try
        {
            var configured = ConfigurationManager.AppSettings["SentryDsn"];
            if (!string.IsNullOrWhiteSpace(configured)) { return configured; }
        }
        catch
        {
            // No App.config, or a platform where the provider cannot initialise at all.
            // Not an error — it is the normal case on mobile.
        }

        var fromEnvironment = Environment.GetEnvironmentVariable("DAQIFI_SENTRY_DSN");
        if (!string.IsNullOrWhiteSpace(fromEnvironment)) { return fromEnvironment; }

        // Baked in at build time from the SentryDsn MSBuild property, so every head gets a
        // DSN without shipping a config file. Absent property -> no attribute -> disabled.
        return typeof(AppLogger).Assembly
            .GetCustomAttributes<AssemblyMetadataAttribute>()
            .FirstOrDefault(a => a.Key == "SentryDsn")?.Value;
    }

    /// <summary>
    /// The environment this build reports events under.
    /// </summary>
    /// <remarks>
    /// Set explicitly for the same reason <c>SendDefaultPii</c> is: it decides which events
    /// count as real. Left to the SDK's own inference, a developer's Debug run, a CI smoke run
    /// and a shipped store build all land in one undifferentiated stream, so the issue list —
    /// and any alert built on it — mixes crashes nobody has hit with crashes users are hitting
    /// right now. That is the difference between a report worth handing to someone to fix and
    /// a report someone has to triage first.
    /// <para>
    /// Overridable, so a local or CI run can label itself without editing the build:
    /// <c>DAQIFI_SENTRY_ENVIRONMENT</c> first, matching the <c>DAQIFI_SENTRY_DSN</c> override
    /// above, then <c>SENTRY_ENVIRONMENT</c> — the variable the SDK itself would have read had
    /// this been left unset, kept working so setting it explicitly costs nothing.
    /// </para>
    /// </remarks>
    private static string ResolveEnvironment()
    {
        var configured = Environment.GetEnvironmentVariable("DAQIFI_SENTRY_ENVIRONMENT")
                         ?? Environment.GetEnvironmentVariable("SENTRY_ENVIRONMENT");
        if (!string.IsNullOrWhiteSpace(configured)) { return configured; }

#if DEBUG
        return "development";
#else
        return "production";
#endif
    }

    // @port: Daqifi.Desktop.Common.Loggers.AppLogger.IsRunningInTestEnvironment
    private static bool IsRunningInTestEnvironment()
    {
        try
        {
            // Check if we're running under a test runner by looking for test assemblies
            var assemblies = AppDomain.CurrentDomain.GetAssemblies();
            var testAssemblies = new[] { "Microsoft.VisualStudio.TestPlatform", "nunit.framework", "xunit" };

            return assemblies.Any(a => testAssemblies.Any(t => a.FullName?.Contains(t) == true));
        }
        catch
        {
            // If anything goes wrong checking the assemblies, assume we're not in test mode
            return false;
        }
    }

    private AppLogger()
    {
        if (IsTestMode)
        {
            // In test mode, don't initialize real logging
            _logger = null;
            _sentryDisposable = null;
            return;
        }

        // Step 1. Create configuration object
        var config = new LoggingConfiguration();

        // Step 2. Create targets and add them to the configuration
        var fileTarget = new FileTarget();
        config.AddTarget("file", fileTarget);

        // Step 3. Set target properties
        fileTarget.CreateDirs = true;
        // Write logs alongside the rest of the app data (see AppDataPaths): machine-wide for
        // elevated production runs, per-user for un-elevated runs (test harness / non-admin
        // Debug). Keeping logs and the database in the same root avoids dropping logs when
        // the machine-wide store is admin-owned and the process is not elevated.
        //
        // This is the first thing in the whole app to touch AppDataPaths, and it does so from
        // inside a static readonly initializer, so AppDataPaths' own initialization MUST be
        // total: anything it throws arrives here as a TypeInitializationException and poisons
        // AppLogger for the life of the process — no file logging, and the global exception
        // handlers rethrowing on their own logging call. A bad DAQIFI_DATA_DIR did exactly that
        // (#127); AppDataPaths now parks that diagnostic in DataDirectoryFault and App.Initialize
        // raises it from a real call site. Keep it that way: resolving these paths must not throw.
        fileTarget.FileName = Path.Combine(AppDataPaths.LogDirectory, "DAQifiAppLog.log");
        fileTarget.Layout = "${longdate} LEVEL=${level:upperCase=true}: ${message}${newline} (${stacktrace}) ${exception:format=tostring} ${newline}";
        fileTarget.KeepFileOpen = false;

        // Setup Archiving
        fileTarget.ArchiveFileName = Path.Combine(AppDataPaths.LogDirectory, "DAQifiAppLog.{#}.log");

        // Archive the log if it gets above 10MB
        fileTarget.ArchiveAboveSize = 10000000;
        fileTarget.ArchiveSuffixFormat = "{#}";

        // Keep a maximum of 5 archives
        fileTarget.MaxArchiveFiles = 5;

        // Step 4. Define rules
        var rule = new LoggingRule("*", LogLevel.Debug, fileTarget);
        config.LoggingRules.Add(rule);

        // Step 5. Activate the configuration
        LogManager.Configuration = config;

        _logger = LogManager.GetCurrentClassLogger();

        // Step 6. Initialize Sentry SDK — explicit CaptureException calls in Error() are the
        // sole capture path; SentryTarget is intentionally omitted to avoid double-reporting.
        var dsn = ResolveSentryDsn();
        // Deliberate divergence from upstream's
        //     Assembly.GetEntryAssembly()?.GetName().Version?.ToString() ?? "0.0.0"
        // which is safe in a single-head WPF app and is not here: the entry assembly is the
        // platform head, and on Android there is no managed entry assembly at all, so every
        // mobile event was tagged with the literal fallback release "0.0.0" (#126). AppVersion
        // reads the shared assembly instead — same answer on every head. See its remarks.
        var version = AppVersion.Informational;

        if (string.IsNullOrWhiteSpace(dsn))
        {
            _logger.Warn("No Sentry DSN resolved — Sentry error reporting is disabled");
            return;
        }

        // Init is guarded because it now writes to the filesystem, and this constructor runs
        // inside a static readonly initializer. SentrySdk.Init does not catch: it builds the
        // caching transport, which calls CreateDirectory on CacheDirectoryPath unguarded. An
        // unwritable directory — a locked-down %ProgramData% ACL on an elevated desktop run, an
        // Android storage failure — would therefore escape the constructor, and the CLR would
        // wrap it as TypeInitializationException and poison the type for the life of the
        // process. Every later AppLogger.Instance access would throw, taking NLog file logging
        // down with it, and on mobile the first touch happens in InitializeMobile() BEFORE the
        // global exception handlers are installed, so the app would die at launch with no trail
        // at all. Degrade the way the missing-DSN path above already does: no Sentry, but the
        // logger still works.
        try
        {
            _sentryDisposable = InitializeSentry(dsn, version);
        }
        catch (Exception ex)
        {
            _sentryDisposable = null;
            _logger.Warn(ex, "Sentry initialisation failed — error reporting is disabled, logging continues");
        }
    }

    private static IDisposable InitializeSentry(string dsn, string? version) =>
        SentrySdk.Init(options =>
        {
            options.Dsn = dsn;
            // Left unset when the version cannot be resolved rather than sent as a placeholder.
            // An unset Release lets the SDK apply its own detection; a stand-in like "0.0.0" is
            // indistinguishable in Sentry from a release that genuinely is 0.0.0, which is
            // precisely how #126 stayed invisible until someone read a crash report closely.
            if (!string.IsNullOrWhiteSpace(version)) { options.Release = version; }
            options.AutoSessionTracking = true;
            options.IsGlobalModeEnabled = true;
            options.Environment = ResolveEnvironment();
            // Explicit, not relying on the SDK default: this app ships to app stores, where
            // "what is collected" is a declaration we have to make and stand behind. No
            // usernames, no email, no IP address attached to events. Sentry's server-side
            // setting scrubs IPs as well; both belt and braces.
            options.SendDefaultPii = false;
            // Persist envelopes to disk so an event survives having nowhere to send it.
            //
            // This is not a nicety on mobile: a DAQiFi is usually reached over its own soft-AP
            // (SSID "DAQiFi-xxxx", 192.168.1.1), and joining it takes the phone OFF the internet
            // for the whole session. Measured on a Galaxy A16 mid-stream: 100% packet loss to
            // 8.8.8.8. Without a cache directory the SDK holds events in memory only, so they
            // die with the process — a probe captured mid-stream never reached Sentry at all,
            // taking its breadcrumb trail with it, which is precisely the activity this app
            // exists for. With one, the same probe landed on disk and was delivered on the next
            // run once the phone was back on a routable network.
            options.CacheDirectoryPath = AppDataPaths.SentryCacheDirectory;
            // Zero, not the SDK's 1s default: any positive value makes Init block the calling
            // thread on a flush attempt, and it waits out the FULL timeout when there is no
            // route — which is exactly the state of a phone still on the soft-AP with a backlog
            // pending. That is the UI thread during cold start, so the cost lands on precisely
            // the sessions this cache exists to serve, on every launch. Zero skips the wait and
            // leaves delivery to the background worker; the envelopes are already durable on
            // disk, so nothing is lost by not waiting for them.
            options.InitCacheFlushTimeout = TimeSpan.Zero;
            // The cache is bounded by MaxCacheItems (measured: 30 by default), so a phone that
            // stays offline discards oldest-first rather than growing without limit.
        });

    #region Logger Methods
    // @port: Daqifi.Desktop.Common.Loggers.AppLogger.Information
    public void Information(string message)
    {
        _logger?.Info(message);
    }

    // @port: Daqifi.Desktop.Common.Loggers.AppLogger.Warning
    public void Warning(string message)
    {
        _logger?.Warn(message);
        LeaveBreadcrumb(message, Sentry.BreadcrumbLevel.Warning);
    }

    // @port: Daqifi.Desktop.Common.Loggers.AppLogger.Warning
    public void Warning(Exception ex, string message)
    {
        // Intentionally no SentrySdk.CaptureException here — the whole point of the
        // exception-aware warning is to keep stack traces in the local log for
        // expected user/environmental conditions without raising a Sentry event.
        _logger?.Warn(ex, message);
        // A breadcrumb is not an event, so this does not undo the line above: it raises no
        // issue and costs no quota. It means that when something DOES get captured later, the
        // expected-but-relevant condition that preceded it is visible in the timeline —
        // the exception type included, since that is the part the message usually omits.
        LeaveBreadcrumb($"{message} — {ex.GetType().Name}: {ex.Message}", Sentry.BreadcrumbLevel.Warning);
    }

    // @port: Daqifi.Desktop.Common.Loggers.AppLogger.Error
    public void Error(string message)
    {
        _logger?.Error(message);
        // A dedicated carrier type rather than the bare System.Exception the scaffold used —
        // see AppLogErrorException for what that buys and, just as important, what it does not.
        SentrySdk.CaptureException(new AppLogErrorException(message));
    }

    // @port: Daqifi.Desktop.Common.Loggers.AppLogger.Error
    public void Error(Exception ex, string message)
    {
        _logger?.Error(ex, message);
        SentrySdk.CaptureException(ex, scope => scope.SetExtra("message", message));
    }

    /// <summary>
    /// Records a warning as a Sentry breadcrumb, so an event captured later carries the
    /// lead-up to it and not just its own stack trace.
    /// </summary>
    /// <remarks>
    /// Warnings only, and the two exclusions are the point.
    /// <para>
    /// <b>Not errors.</b> The SDK already writes a breadcrumb for every captured exception —
    /// verified against 6.8.0, which emits one with category "Exception" carrying the
    /// exception's message. Adding our own would put the same failure in the timeline twice.
    /// The contextual message that the SDK's breadcrumb does not carry is not lost either: it
    /// travels on the event itself, via the <c>SetExtra("message", …)</c> above.
    /// </para>
    /// <para>
    /// <b>Not information.</b> It is the highest-volume level and the lowest-value one, the
    /// breadcrumb ring is bounded (SDK default 100), and the app already places explicit
    /// <see cref="AddBreadcrumb"/> calls at the moments that actually matter — connect,
    /// disconnect, streaming start/stop, firmware transitions, discovery, export. Letting
    /// routine chatter push those out of the ring would trade the informative half of the
    /// timeline for the dull half.
    /// </para>
    /// <para>
    /// Warnings are the real gap: <see cref="Warning(Exception, string)"/> deliberately does
    /// not capture, so nothing else records it, and it is exactly the expected-but-relevant
    /// condition — a refused SD operation, a dropped connection, a retry — that explains the
    /// crash that follows it.
    /// </para>
    /// </remarks>
    private static void LeaveBreadcrumb(string message, Sentry.BreadcrumbLevel level) =>
        SentrySdk.AddBreadcrumb(message: message, category: "log", level: level);

    /// <inheritdoc />
    // @port: Daqifi.Desktop.Common.Loggers.AppLogger.AddBreadcrumb
    public void AddBreadcrumb(string category, string message, BreadcrumbLevel level = BreadcrumbLevel.Info)
    {
        SentrySdk.AddBreadcrumb(
            message: message,
            category: category,
            level: MapBreadcrumbLevel(level));
    }

    /// <inheritdoc />
    // @port: Daqifi.Desktop.Common.Loggers.AppLogger.SetDeviceContext
    public void SetDeviceContext(string model, string serialNumber, string firmwareVersion, string connectionType, int activeChannels)
    {
        SentrySdk.ConfigureScope(scope =>
        {
            scope.SetTag("daqifi.device_model", model ?? "unknown");
            scope.SetTag("daqifi.serial_number", serialNumber ?? "unknown");
            scope.SetTag("daqifi.firmware_version", firmwareVersion ?? "unknown");
            scope.SetTag("daqifi.connection_type", connectionType);
            scope.SetTag("daqifi.active_channels", activeChannels.ToString(System.Globalization.CultureInfo.InvariantCulture));
        });
    }

    /// <inheritdoc />
    // @port: Daqifi.Desktop.Common.Loggers.AppLogger.ClearDeviceContext
    public void ClearDeviceContext()
    {
        SentrySdk.ConfigureScope(scope =>
        {
            scope.UnsetTag("daqifi.device_model");
            scope.UnsetTag("daqifi.serial_number");
            scope.UnsetTag("daqifi.firmware_version");
            scope.UnsetTag("daqifi.connection_type");
            scope.UnsetTag("daqifi.active_channels");
        });
    }

    /// <inheritdoc />
    // @port: Daqifi.Desktop.Common.Loggers.AppLogger.Shutdown
    public void Shutdown()
    {
        SentrySdk.FlushAsync(TimeSpan.FromSeconds(2)).GetAwaiter().GetResult();
        _sentryDisposable?.Dispose();
    }

    // @port: Daqifi.Desktop.Common.Loggers.AppLogger.MapBreadcrumbLevel
    private static Sentry.BreadcrumbLevel MapBreadcrumbLevel(BreadcrumbLevel level)
    {
        return level switch
        {
            BreadcrumbLevel.Debug => Sentry.BreadcrumbLevel.Debug,
            BreadcrumbLevel.Info => Sentry.BreadcrumbLevel.Info,
            BreadcrumbLevel.Warning => Sentry.BreadcrumbLevel.Warning,
            BreadcrumbLevel.Error => Sentry.BreadcrumbLevel.Error,
            BreadcrumbLevel.Critical => Sentry.BreadcrumbLevel.Error,
            _ => Sentry.BreadcrumbLevel.Info
        };
    }
    #endregion
}
